package com.bank.support.service;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Generates all keypad letter spellings of a digit code via backtracking.
public class PhoneLetterService {
    private static final Logger log = Logger.getLogger(PhoneLetterService.class.getName());

    private static final Map<Character, String> KEYPAD = Map.of(
            '2', "abc", '3', "def", '4', "ghi", '5', "jkl",
            '6', "mno", '7', "pqrs", '8', "tuv", '9', "wxyz");

    public List<String> letterCombinations(String digits) {
        List<String> result = new ArrayList<>();
        if (digits == null || digits.isEmpty()) {
            return result; // conventional: empty input → empty result
        }
        backtrack(digits, 0, new StringBuilder(), result);
        log.info(() -> "Generated " + result.size() + " spellings for " + digits);
        return result;
    }

    private void backtrack(String digits, int index,
                           StringBuilder current, List<String> result) {
        if (index == digits.length()) {
            result.add(current.toString());
            log.fine(() -> "Completed spelling " + current);
            return;
        }
        String letters = KEYPAD.get(digits.charAt(index));
        for (int i = 0; i < letters.length(); i++) {
            current.append(letters.charAt(i)); // choose a letter
            backtrack(digits, index + 1, current, result);
            current.deleteCharAt(current.length() - 1); // backtrack
        }
    }
}
