package com.bank.support;

import com.bank.support.service.PhoneLetterService;
import java.util.logging.Logger;

public class PhoneLetterApplication {
    private static final Logger log = Logger.getLogger(PhoneLetterApplication.class.getName());

    public static void main(String[] args) {
        PhoneLetterService service = new PhoneLetterService();
        // Code "23" → 3 letters × 3 letters = 9 spellings.
        log.info("NBI vanity code '23' spellings: " + service.letterCombinations("23"));
    }
}
